from pathlib import Path

repo = Path('/testbed')
inst = Path('/testbed/qa_instances_eval/python-control/timeresp_check_convert_array_def_use_intersection_suite')

target_vars = {
    'err_msg','err_msg_start','in_obj','legal_kinds','legal_shape_str','legal_shapes',
