def collect_maps(fn_node):
    uses = defaultdict(set)
    defs = defaultdict(set)
    for n in ast.walk(fn_node):
        if hasattr(n, 'lineno'):
            if isinstance(n, ast.Name) and n.id in target_vars:
                if isinstance(n.ctx, ast.Load):
                    uses[n.lineno].add(n.id)
                elif isinstance(n.ctx, (ast.Store, ast.Del)):
                    defs[n.lineno].add(n.id)
    return uses, defs

uses_check, defs_check = collect_maps(check_fn)
uses_shape, defs_shape = collect_maps(shape_fn)

# test module import
