spec.loader.exec_module(qa)

sys.path.insert(0, str(repo))
import control.timeresp as timeresp

# Ensure function module loaded

test_names = [f'test_case_{i:02d}' for i in range(1,11)]

all_sets = []

for tname in test_names:
    last_def = {}
    pairs = set()

    def tracer(frame, event, arg):
        nonlocal last_def, pairs
        if frame.f_code.co_filename != str(src_path):
            return tracer

        name = frame.f_code.co_name
        if event == 'call':
            if name == '_check_convert_array':
                for p in ['in_obj','legal_shapes','err_msg_start','squeeze','transpose']:
                    last_def[p] = 811
            elif name == 'shape_matches':
                for p in ['s_legal','s_actual']:
                    last_def[p] = 886
            return tracer

        if event == 'line':
            ln = frame.f_lineno
            if name == '_check_convert_array':
                uses, defs = uses_check.get(ln, ()), defs_check.get(ln, ())
            elif name == 'shape_matches':
                uses, defs = uses_shape.get(ln, ()), defs_shape.get(ln, ())
            else:
                return tracer

            # Record uses before defs on same line
            for v in uses:
                if v in last_def:
                    pairs.add((v, last_def[v], ln))
            for v in defs:
                last_def[v] = ln

        return tracer

    inst_obj = qa.TestCheckConvertArrayDefUseIntersectionQA()
    method = getattr(inst_obj, tname)
    oldtrace = sys.gettrace()
    sys.settrace(tracer)
    try:
        method()
    finally:
        sys.settrace(oldtrace)

    all_sets.append(pairs)

inter = set.intersection(*all_sets)
# sort
result = sorted(inter, key=lambda x: (x[0], x[1], x[2]))
print('INTERSECTION COUNT', len(result))
for r in result:
    print(r)

